# 1.8 – 1.19 после них, таблица функциональных требований становится 1.20.

def uc(actor, brief, fr, pre, main, alt, post):
    return [
        ('Действующее лицо', actor),
        ('Краткое описание', brief),
        ('Связанные требования', fr),
        ('Входные условия', pre),
        ('Основной поток действий', main),
        ('Альтернативные потоки действий', alt),
        ('Выходные условия', post),
    ]

def steps(*items):
    return [f'{i}. {t}' for i, t in enumerate(items, 1)]

